#if UNITY_EDITOR
using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace IslandSystem {
public class ActionReview:MonoBehaviour {
 readonly List<string> report=new List<string>();ActionMotor motor;
 void Assert(bool pass,string description){report.Add((pass?"PASS ":"FAIL ")+description);File.WriteAllLines("Logs/ActionReview.txt",report);if(!pass)throw new Exception(description);}
 IEnumerator Start(){yield return new WaitForSeconds(.6f);motor=FindAnyObjectByType<ActionMotor>();float groundedDeadline=Time.realtimeSinceStartup+4;while(motor&&!motor.Grounded&&Time.realtimeSinceStartup<groundedDeadline)yield return null;try{UnityEngine.Debug.Log("MOTOR_DIAG "+(motor?motor.transform.position+" grounded="+motor.Grounded+" body="+motor.GetComponent<CharacterController>().isGrounded:"MISSING setup="+(FindAnyObjectByType<ActionSceneSetup>()!=null)));if(motor)Shot("00-Diagnostic");Assert(motor&&motor.Grounded,"Existing lighthouse scene motor grounded");Assert(motor.animator.avatar.isHuman&&motor.animator.avatar.isValid,"Humanoid avatar and action animation retarget valid");}catch(Exception e){Fail(e);yield break;}
  foreach(var w in FindObjectsByType<Workbench>())w.enabled=false;var root=new GameObject("Action test bridge");root.SetActive(false);var host=root.AddComponent<ScratchWorkbenchHost>();host.BackgroundReview=true;host.SavePathOverride=Path.GetFullPath("Logs/action-review-save.json");root.SetActive(true);host.ReviewToggle(true);string url=host.ReviewStartBridge();
  var process=Process.Start(new ProcessStartInfo("node","\""+Path.GetFullPath("Tools/IslandScratchWeb/action-review.mjs")+"\" "+url){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true});var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();float timeout=Time.realtimeSinceStartup+70;bool shotJump=false,shotChop=false;
  while(!process.HasExited&&Time.realtimeSinceStartup<timeout){if(!shotJump&&motor.Jumps>0&&!motor.Grounded&&motor.transform.position.y>motor.Spawn.y+.65f){Shot("02-Jump");shotJump=true;}if(!shotChop&&motor.Busy&&motor.ChopPhase>.36f){Shot("03-Chop");shotChop=true;}yield return null;}
  try{Assert(process.HasExited&&process.ExitCode==0,"Official Scratch browser → Unity run RPC → real motor: "+output.Result+error.Result);Assert(motor.Jumps==3&&motor.Landings==3,"Repeat 3 jump = 3 real airborne and landing cycles");Assert(motor.Chops==3,"Repeat 3 chop = 3 contact events");bool fallen=false;foreach(var t in FindObjectsByType<ChopTarget>())if(t.Felled&&t.DroppedLogs==3)fallen=true;Assert(fallen,"Tree felled and 3 physical world wood props spawned");Assert(!motor.InputBlocked,"Closing workbench releases motor input");Shot("04-Tree-Felled");}catch(Exception e){Fail(e);yield break;}
  motor.Teleport(motor.Spawn+Vector3.right*1.8f);yield return new WaitForSeconds(.2f);var actionRunner=motor.GetComponent<ActionProgramRunner>();var travelStart=motor.transform.position;motor.transform.rotation=Quaternion.identity;var travel=new Draft();travel.blocks.Add(new Block{kind=0});travel.blocks.Add(new Block{kind=11,value="90"});travel.blocks.Add(new Block{kind=10,value="2"});actionRunner.Execute(travel);while(actionRunner.Running)yield return null;
  try{Assert(actionRunner.LastError==""&&Mathf.Abs(Mathf.DeltaAngle(motor.transform.eulerAngles.y,90))<1&&motor.transform.position.x-travelStart.x>1.85f,"Turn 90 and move 2m blocks change actual rotation and position");}catch(Exception e){Fail(e);yield break;}
  motor.Teleport(motor.Spawn+Vector3.right*1.8f);yield return new WaitForSeconds(.2f);motor.Yaw=0;var start=motor.transform.position;motor.ReviewAxes=Vector2.right;yield return new WaitForSeconds(.4f);motor.ReviewAxes=Vector2.zero;float side=(motor.transform.position-start).x;
  try{Assert(side>.8f,"A/D lateral movement uses camera space, displacement="+side);}catch(Exception e){Fail(e);yield break;}
  motor.Teleport(motor.Spawn+Vector3.right*1.8f);yield return new WaitForSeconds(.2f);start=motor.transform.position;motor.ReviewAxes=Vector2.right;motor.ReviewSprint=true;yield return new WaitForSeconds(.4f);motor.ReviewAxes=Vector2.zero;motor.ReviewSprint=false;
  try{Assert((motor.transform.position-start).x>side*1.5f,"Shift increases physical travel speed");float yaw=motor.Yaw,dist=motor.Distance;motor.Orbit(30,5,1);Assert(motor.Yaw==yaw+30&&motor.Distance<dist,"Mouse orbit and wheel distance use runtime camera path");host.ReviewToggle(true);Assert(motor.InputBlocked,"Opening workbench blocks only manual input");host.ReviewToggle(false);Assert(!motor.InputBlocked,"Closing workbench restores input");Assert(Time.timeScale==1,"World timescale preserved");var runner=motor.GetComponent<ActionProgramRunner>();var d=new Draft();d.blocks.Add(new Block{kind=0});d.blocks.Add(new Block{kind=3,value="10"});runner.Execute(d);runner.Cancel();Assert(!runner.Running&&!motor.Busy,"Cancel releases program ownership");motor.Teleport(motor.Spawn);motor.Yaw=0;motor.Pitch=22;motor.Distance=5.5f;Shot("01-Lighthouse-Play");File.WriteAllLines("Docs/IslandSystem/ActionTrial/RuntimeReview.txt",report);EditorApplication.isPlaying=false;}catch(Exception e){Fail(e);}
 }
 void Fail(Exception e){UnityEngine.Debug.LogException(e);EditorApplication.Exit(2);}
 void Shot(string name){Directory.CreateDirectory("Docs/IslandSystem/ActionTrial");var camera=motor.view;var old=camera.targetTexture;var oldActive=RenderTexture.active;var rt=new RenderTexture(1280,720,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes("Docs/IslandSystem/ActionTrial/"+name+".png",image.EncodeToPNG());camera.targetTexture=old;RenderTexture.active=oldActive;Destroy(image);Destroy(rt);}
}
[InitializeOnLoad]public static class ActionReviewEntry {
 static ActionReviewEntry(){if(SessionState.GetBool("ActionReview",false))EditorApplication.playModeStateChanged+=Attach;}
 public static void Run(){if(!Application.isBatchMode)throw new Exception("Background only");EditorSceneManager.OpenScene("Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity");SessionState.SetBool("ActionReview",true);EditorApplication.playModeStateChanged+=Attach;EditorApplication.isPlaying=true;}
 static void Attach(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("Background real action review").AddComponent<ActionReview>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("ActionReview",false);EditorApplication.Exit(0);}}
}
}
#endif
